int AtIoJamFileSystem::GetFileInfo(const char* path, AtIoFileStat* stat) {
    m_path.Resolve(path);
    char relative[0x10C];
    if (!m_path.Join(relative, 0x10C, path)) {
        AtFatal("AtIoWinFileSystem::eOpen:  relative path name too long!\n", 0, 0, 0);
    }
    int found;
    unsigned int recordHeader = 0;
    switch (m_info.m_token) {
        case AtIoJamInfoHeader::kJam1:
            found = static_cast<AtIoJam1Header*>(m_header)->GetFileInfo(m_path.m_full, &stat->m_offset, &stat->m_size);
            recordHeader = 0x20;
            break;
        case AtIoJamInfoHeader::kJam2:
            found = static_cast<AtIoFastJamHeader*>(m_header)->GetFileInfo(m_path.m_full, &stat->m_offset, &stat->m_size);
            recordHeader = 0x20;
            break;
        case AtIoJamInfoHeader::kFsta:
        case AtIoJamInfoHeader::kFstr:
            found = static_cast<AtIoFastAlignedJamHeader*>(m_header)->FindFileInfo(m_path.m_full, &stat->m_offset, &stat->m_size);
            break;
        default:
            return 1;
    }
    if (!found) {
        return 1;
    }
    stat->m_offset += recordHeader;
    stat->m_time = m_archiveTime;
    strncpy(stat->m_name, m_archiveName, 0x10C);
    return 0;
}

